"use strict";
const assert=require("node:assert/strict");
const fs=require("node:fs"),path=require("node:path"),vm=require("node:vm");
const root=path.resolve(__dirname,"..");
const source=fs.readFileSync(path.join(root,"assets/session-effects-2024.js"),"utf8");
const style=fs.readFileSync(path.join(root,"assets/session-effects-2024.css"),"utf8");
const html=fs.readFileSync(path.join(root,"index.html"),"utf8");
const context={};vm.runInNewContext(source,context,{filename:"session-effects-2024.js"});
const api=context.DND5RSessionEffects;
assert(api,"2024 status runtime missing");
const expected=["blinded","charmed","deafened","exhaustion","frightened","grappled","incapacitated","invisible","paralyzed","petrified","poisoned","prone","restrained","stunned","unconscious","concentration"];
assert.equal(api.DEFINITIONS.length,15,"all PHB2024 conditions must remain");
assert.deepEqual(Array.from(api.DEFINITIONS,x=>x[0]),expected.slice(0,15),"reference IDs/order changed");
assert.equal(new Set(expected).size,16);
const play={conditions2024:{},exhaustion2024:0,concentration2024:""};
const markup=api.html(play,"2024");
for(const [n,id] of expected.entries()){
 const occurrence=markup.match(new RegExp('data-status-art="'+id+'"','g'))||[];
 assert.equal(occurrence.length,1,"icon missing or duplicate in selectable controls: "+id);
 const element=markup.match(new RegExp('<span class="session-watercolor-icon[^>]*data-status-art="'+id+'"[^>]*>'))?.[0]||"";
 assert(element.includes('aria-hidden="true"'),id+" missing accessible decorative markup");
 const pos=["0%","33.333333%","66.666667%","100%"];
 assert(element.includes('--wc-x:'+pos[n%4]),id+' unexpected X sprite slot');
 assert(element.includes('--wc-y:'+pos[Math.floor(n/4)]),id+' unexpected Y sprite slot');
}
assert(!markup.includes('session-chip-icon'),'old glyph in main condition UI');
assert.equal(api.html(play,"2014"),"","2014 branch altered");
const toggled={conditions2024:{grappled:true,restrained:true},exhaustion2024:1,concentration2024:"\u5c08\u6ce8"};
const top=api.summaryHTML(toggled,"2024");
for(const id of ["grappled","restrained","exhaustion","concentration"]) assert(top.includes('data-status-art="'+id+'"'),"active status chip missing watercolor art: "+id);
assert(api.summaryHTML(toggled,"2014")==="","2014 active UI altered");
assert(style.includes('status-watercolor-2024.webp'),"WebP stylesheet ref missing");
assert(style.includes('background-size:400% 400%')||style.includes('/400% 400%'),"sprite grid scaling missing");
for(const kind of ["js","css"]) assert(html.includes('session-effects-2024.'+kind+'?v=20261120-watercolor-v1'),"cache bust missing: "+kind);
const image=path.join(root,"assets/status-watercolor-2024.webp");
assert(fs.existsSync(image),"watercolor atlas is not in release worktree");
const buf=fs.readFileSync(image);assert(buf.length>6500 && buf.length<90000,"unexpected atlas size");
assert.equal(buf.toString("ascii",0,4),"RIFF");assert.equal(buf.toString("ascii",8,12),"WEBP");
console.log("STATUS_WATERCOLOR_16_OF_16_PASS",JSON.stringify({effects:15,concentration:1,unique:16,grappledSlot:5,restrainedSlot:12,atlasBytes:buf.length,sourceStateSchemaUnchanged:true}));
